    return subprocess.check_output(cmd, shell=True, text=True).strip()


def list_all():
    out = run('wezterm cli list --format json')
    return json.loads(out)


def get_tab_id_for_pane(pane_id):
    for p in list_all():
        if p['pane_id'] == pane_id:
            return p['tab_id'], p['window_id']
    raise RuntimeError(f'pane {pane_id} not found')


def list_tab(tab_id):
    return [p for p in list_all() if p['tab_id'] == tab_id]


def ranges_overlap(a_start, a_size, b_start, b_size):
    a_end = a_start + a_size
    b_end = b_start + b_size
    return a_start < b_end and b_start < a_end


def touches(a, b):
    return abs(a - b) <= 1


def panes_touch(axis, a, b):
    if axis == 'x':
        a_right = a['left_col'] + a['size']['cols']
        b_right = b['left_col'] + b['size']['cols']
        horiz_adj = touches(a_right, b['left_col']) or touches(b_right, a['left_col'])
        return horiz_adj and ranges_overlap(a['top_row'], a['size']['rows'], b['top_row'], b['size']['rows'])
    a_bottom = a['top_row'] + a['size']['rows']
    b_bottom = b['top_row'] + b['size']['rows']
    vert_adj = touches(a_bottom, b['top_row']) or touches(b_bottom, a['top_row'])
    return vert_adj and ranges_overlap(a['left_col'], a['size']['cols'], b['left_col'], b['size']['cols'])


def collect_connected(tab_panes, start_pane_id, axis):
    by_id = {p['pane_id']: p for p in tab_panes}
    start = by_id.get(start_pane_id)
    if not start:
        return []
    q = [start]
    seen = {start_pane_id}
    out = []
    i = 0
    while i < len(q):
        cur = q[i]
        i += 1
        out.append(cur)
        for cand in tab_panes:
            cid = cand['pane_id']
            if cid in seen:
                continue
            if panes_touch(axis, cur, cand):
                seen.add(cid)
                q.append(cand)
    key = 'left_col' if axis == 'x' else 'top_row'
    out.sort(key=lambda p: (p[key], p['pane_id']))
    return out


def max_error(conn, axis):
    if len(conn) <= 1:
        return 0
    key = 'cols' if axis == 'x' else 'rows'
    total = sum(p['size'][key] for p in conn)
    base = total // len(conn)
    rem = total - (base * len(conn))
    m = 0
    for i, p in enumerate(conn, start=1):
        tgt = base + (1 if i <= rem else 0)
        m = max(m, abs(p['size'][key] - tgt))
    return m


def rebalance(tab_id, source_pane_id, axis, passes=20):
    prev_dir = 'Left' if axis == 'x' else 'Up'
    next_dir = 'Right' if axis == 'x' else 'Down'
    key = 'cols' if axis == 'x' else 'rows'

    for _ in range(passes):
        tab = list_tab(tab_id)
        conn = collect_connected(tab, source_pane_id, axis)
        if len(conn) <= 1:
            return conn
        total = sum(p['size'][key] for p in conn)
        base = total // len(conn)
        rem = total - (base * len(conn))

        for i in range(len(conn) - 1):
            cur = conn[i]
            nxt = conn[i + 1]
            tgt = base + (1 if (i + 1) <= rem else 0)
            delta = cur['size'][key] - tgt
            if delta < 0:
                run(f"wezterm cli adjust-pane-size --pane-id {cur['pane_id']} --amount {abs(delta)} {next_dir}")
            elif delta > 0:
                run(f"wezterm cli adjust-pane-size --pane-id {nxt['pane_id']} --amount {abs(delta)} {prev_dir}")

        time.sleep(0.015)
        tab = list_tab(tab_id)
        conn = collect_connected(tab, source_pane_id, axis)
        if max_error(conn, axis) <= 1:
            return conn

    return collect_connected(list_tab(tab_id), source_pane_id, axis)


def print_layout(tab_id, axis, source_pane_id, label):
    tab = list_tab(tab_id)
    conn = collect_connected(tab, source_pane_id, axis)
    key = 'cols' if axis == 'x' else 'rows'
    vals = [p['size'][key] for p in conn]
    print(f"{label}: count={len(conn)} sizes={vals} max_error={max_error(conn, axis)}")

created = []
try:
    root = int(run("wezterm cli spawn --new-window -- zsh -lc 'sleep 600'"))
    created.append(root)
    tab_id, window_id = get_tab_id_for_pane(root)
    source = root

    print(f"test window={window_id} tab={tab_id} root={root}")

    # Repeated left splits with rebalance
    for step in range(1, 7):
        new_pane = int(run(f"wezterm cli split-pane --pane-id {source} --left -- zsh -lc 'sleep 600'"))
        created.append(new_pane)
        source = new_pane
        rebalance(tab_id, source, 'x', passes=20)
        print_layout(tab_id, 'x', source, f"left split step {step}")

    # Repeated top splits with rebalance in the current top-most chain
    for step in range(1, 7):
        new_pane = int(run(f"wezterm cli split-pane --pane-id {source} --top -- zsh -lc 'sleep 600'"))
        created.append(new_pane)
        source = new_pane
        rebalance(tab_id, source, 'y', passes=20)
        print_layout(tab_id, 'y', source, f"top split step {step}")

finally:
    for pid in reversed(created):
        try:
            run(f"wezterm cli kill-pane --pane-id {pid}")
        except Exception:
