import json, subprocess, itertools

def run(cmd):
    return subprocess.check_output(cmd, shell=True, text=True).strip()

def list_all():
    return json.loads(run('wezterm cli list --format json'))

def pane_row(pid):
    for p in list_all():
        if p['pane_id']==pid:
            return p
    return None

def tab_rows(tab_id):
    return [p for p in list_all() if p['tab_id']==tab_id]

def sorted_by_x(rows):
    return sorted(rows, key=lambda p: p['left_col'])

def sorted_by_y(rows):
    return sorted(rows, key=lambda p: p['top_row'])


def setup_horizontal_two():
    created=[]
    root=int(run("wezterm cli spawn --new-window -- zsh -lc 'sleep 600'")); created.append(root)
    r=int(run(f"wezterm cli split-pane --pane-id {root} --right -- zsh -lc 'sleep 600'")); created.append(r)
    tab=pane_row(root)['tab_id']
    rows=sorted_by_x(tab_rows(tab))
    return created,tab,rows

def setup_horizontal_three():
    created=[]
    root=int(run("wezterm cli spawn --new-window -- zsh -lc 'sleep 600'")); created.append(root)
    r=int(run(f"wezterm cli split-pane --pane-id {root} --right -- zsh -lc 'sleep 600'")); created.append(r)
    m=int(run(f"wezterm cli split-pane --pane-id {r} --left -- zsh -lc 'sleep 600'")); created.append(m)
    tab=pane_row(root)['tab_id']
    rows=sorted_by_x(tab_rows(tab))
    return created,tab,rows


def setup_vertical_three():
    created=[]
    root=int(run("wezterm cli spawn --new-window -- zsh -lc 'sleep 600'")); created.append(root)
    b=int(run(f"wezterm cli split-pane --pane-id {root} --bottom -- zsh -lc 'sleep 600'")); created.append(b)
    m=int(run(f"wezterm cli split-pane --pane-id {b} --top -- zsh -lc 'sleep 600'")); created.append(m)
    tab=pane_row(root)['tab_id']
    rows=sorted_by_y(tab_rows(tab))
    return created,tab,rows


def cleanup(pids):
    for pid in reversed(pids):
        try: run(f"wezterm cli kill-pane --pane-id {pid}")
        except Exception: pass


def measure(tab_id, axis='x'):
    rows=tab_rows(tab_id)
    if axis=='x':
        rows=sorted_by_x(rows)
        return [(p['pane_id'], p['left_col'], p['size']['cols']) for p in rows]
    rows=sorted_by_y(rows)
    return [(p['pane_id'], p['top_row'], p['size']['rows']) for p in rows]

print('=== two-pane horizontal behavior ===')
for pane_pos in ('left','right'):
    for direction in ('Left','Right'):
        created=[]
        try:
            created,tab,rows=setup_horizontal_two()
            target = rows[0] if pane_pos=='left' else rows[1]
            before=measure(tab,'x')
            run(f"wezterm cli adjust-pane-size --pane-id {target['pane_id']} --amount 5 {direction}")
            after=measure(tab,'x')
            print(f"pane={pane_pos:5} dir={direction:5} before={before} after={after}")
        finally:
            cleanup(created)

print('\n=== three-pane horizontal behavior (middle pane) ===')
for direction in ('Left','Right'):
    created=[]
    try:
        created,tab,rows=setup_horizontal_three()
        middle=rows[1]
        before=measure(tab,'x')
        run(f"wezterm cli adjust-pane-size --pane-id {middle['pane_id']} --amount 5 {direction}")
        after=measure(tab,'x')
        print(f"middle dir={direction:5} before={before} after={after}")
    finally:
        cleanup(created)

print('\n=== three-pane vertical behavior (middle pane) ===')
for direction in ('Up','Down'):
    created=[]
    try:
        created,tab,rows=setup_vertical_three()
        middle=rows[1]
        before=measure(tab,'y')
        run(f"wezterm cli adjust-pane-size --pane-id {middle['pane_id']} --amount 3 {direction}")
        after=measure(tab,'y')
        print(f"middle dir={direction:5} before={before} after={after}")
    finally:
        cleanup(created)
