import json, subprocess

def run(c): return subprocess.check_output(c,shell=True,text=True).strip()
def lst(): return json.loads(run('wezterm cli list --format json'))

def rows(tab):
    return sorted([p for p in lst() if p['tab_id']==tab], key=lambda p:(p['top_row'],p['left_col']))

def print_rows(tab,label):
    print(label)
    for p in rows(tab):
        print(' ',p['pane_id'],'left',p['left_col'],'top',p['top_row'],'w',p['size']['cols'],'h',p['size']['rows'])

created=[]
try:
    root=int(run("wezterm cli spawn --new-window -- zsh -lc 'sleep 600'")); created.append(root)
    tab=[p for p in lst() if p['pane_id']==root][0]['tab_id']
    src=root
    print_rows(tab,'initial')
    for step in range(1,4):
        n=len(rows(tab))
        pct=max(1,100//(n+1))
        src=int(run(f"wezterm cli split-pane --pane-id {src} --left --top-level --percent {pct} -- zsh -lc 'sleep 600'")); created.append(src)
        print_rows(tab,f'after step {step} pct={pct}')
finally:
    for pid in reversed(created):
        try: run(f"wezterm cli kill-pane --pane-id {pid}")
        except Exception: pass
